//! mina: daemon/client 分割のターミナルエディタ（bin クレート）。
//!
//! モード:
//! - `mina daemon serve` — 常駐デーモン（クライアントから自動起動されることもある）
//! - `mina [file]` — クライアント（S0 では GetState の表示のみ。TUI は S1）

mod client;
mod daemon;
mod keymap;
mod lsp;
mod render;
mod session;

#[tokio::main]
